<main id="main" class="shell"><header class="page-heading"><p class="eyebrow">Your next escape</p><h1>A few details. A new beginning.</h1><p>Choose your room, tell us who is coming, and take the next step towards your stay.</p><div class="booking-steps"><span>01 · Explore</span><i></i><span class="current">02 · Your details</span><i></i><span>03 · Reservation</span></div></header><?php require __DIR__.'/partials/errors.php'; ?><form action="/booking" method="POST" class="checkout-layout" data-date-form><div class="surface"><section class="checkout-section"><h2><span class="step-number">01</span>Your stay</h2><div class="form-grid"><div class="field span-full"><label for="room_id">Choose a room</label><select id="room_id" name="room_id" required data-room-select><option value="">Choose a room</option><?php foreach($rooms as $room): ?><option value="<?= (int)$room['id'] ?>" <?= (int)$room['id']===$roomId?'selected':'' ?> data-price="<?= (float)$room['price'] ?>" data-capacity="<?= (int)$room['capacity'] ?>" data-title="<?= ns_e($room['title']) ?>"><?= ns_e($room['title']) ?> — NPR <?= ns_money($room['price']) ?> / night · up to <?= (int)$room['capacity'] ?> guests</option><?php endforeach; ?></select></div><div class="field"><label for="check_in">Check-in</label><input id="check_in" name="check_in" type="date" value="<?= ns_e($checkIn) ?>" min="<?= ns_e($today) ?>" required data-check-in></div><div class="field"><label for="check_out">Check-out</label><input id="check_out" name="check_out" type="date" value="<?= ns_e($checkOut) ?>" min="<?= ns_e($today) ?>" required data-check-out></div><div class="field span-full"><label for="num_guests">Number of guests</label><input id="num_guests" name="num_guests" type="number" value="<?= (int)$numGuests ?>" min="1" required></div></div></section><section class="checkout-section"><h2><span class="step-number">02</span>Your details</h2><div class="form-grid"><div class="field span-full"><label for="guest_name">Full name</label><input id="guest_name" name="guest_name" autocomplete="name" value="<?= ns_e($guestName) ?>" required></div><div class="field"><label for="guest_email">Email address</label><input id="guest_email" name="guest_email" type="email" autocomplete="email" value="<?= ns_e($guestEmail) ?>" required></div><div class="field"><label for="guest_phone">Phone number</label><input id="guest_phone" name="guest_phone" type="tel" autocomplete="tel" value="<?= ns_e($guestPhone) ?>" required></div></div></section><section class="checkout-section"><button class="button button-full" type="submit" <?= !$rooms?'disabled':'' ?>>Submit reservation <?= ns_icon('arrow') ?></button><p class="field-help" style="margin-top:14px">Your reservation will be recorded as pending. Submitting this form does not process a payment.</p></section></div><aside class="booking-summary"><img src="/Assets/images/bg.jpg" alt="A glimpse of the Himalayas"><p class="eyebrow">Something to look forward to</p><h2 data-summary-room>Your NepalStay escape</h2><div class="summary-row"><span>Length of stay</span><strong data-summary-nights>Select your dates</strong></div><div class="summary-row"><span>Reservation status</span><strong>Pending on submission</strong></div><div class="summary-total"><span class="label">Estimated room total</span><strong data-summary-total>Select room &amp; dates</strong><small>Your final reservation total appears on your receipt.</small></div><div class="info-note"><strong>Keep your stay close</strong><?php if($isSignedIn): ?>This reservation will appear in your account.<?php else: ?><a href="/login" class="text-link">Sign in before booking</a> to save this reservation in your account, or continue as a guest and save your receipt.<?php endif; ?></div></aside></form></main><?php require __DIR__.'/partials/footer.php'; ?>